  const [siteDrafts,setSiteDrafts]=useState<PartySiteDraft[]>([]);
  const roleSaveHandlers=useRef(new Map<string,()=>Promise<void>>());
  const registerRoleSave=useCallback((key:string,handler:()=>Promise<void>)=>{roleSaveHandlers.current.set(key,handler);return()=>{if(roleSaveHandlers.current.get(key)===handler)roleSaveHandlers.current.delete(key)}},[]);
  const systemParty=Boolean(detail&&isFinalConsumer(detail));
  useEffect(()=>{if(!detail)return;setName(detail.displayName);setLegalName(detail.legalName??"");setFirstName(detail.firstName??"");setLastName(detail.lastName??"");setVerificationDigit(detail.verificationDigit??"");setEmail(detail.email??"");setPhone(detail.phone??"");setCustomerPriceChannelId(detail.customer?.priceChannelId??"");setCustomerRequiresInvoice(detail.customer?.requiresElectronicInvoice??false);setCustomerPriceValidFrom(detail.customer?.validFrom?.slice(0,10)??todayInput());setCustomerPriceValidUntil(detail.customer?.validUntil?.slice(0,10)??"");setSupplierEvidencePolicy(detail.supplier?.purchaseEvidencePolicy??"Unconfigured");setSupplierPaymentDueDays(String(detail.supplier?.defaultPaymentDueDays??30));setSellerCode(detail.seller?.code??"");setSellerCommission(detail.seller?.defaultCommissionPercent==null?"":String(detail.seller.defaultCommissionPercent));setSellerBasis(detail.seller?.commissionBasis??"SaleAfterTax");setSellerTrigger(detail.seller?.commissionTrigger??"Sale");setCarrierCode(detail.carrier?.code??"");setCarrierMode(detail.carrier?.transportationMode??"Road");setSiteDrafts((detail.sites?.length?detail.sites:detail.primarySite?[detail.primarySite]:[]).map(partySiteDraft));if(isFinalConsumer(detail))setEditing(false)},[detail]);
  if(!target)return null;
